def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/environment/input/boston-harbor-beaches.txt'
    with open(path, 'r', encoding='utf-8', errors='replace') as f:
        lines = f.readlines()[:60]
    return pd.DataFrame({'line_no': range(1, len(lines)+1), 'line': [l.rstrip('\n') for l in lines]})

